              null,
              null,
              null,
              'u64',
              'u64',
              'u64',
              'u64',
              '0x2::accumulator::AccumulatorRoot',
              '0x2::clock::Clock'
            ],
            [
              'market',
              'wrapper',
              'auth',
              'config',
              'pricer',
              'lowerTick',
              'higherTick',
              'maxCost',
              'minQuantity'
            ]),
      );
}

